@CrossOrigin
@RestController
@RequestMapping("/PredictionQuery")
public class PredictionQueryRestController extends BaseSpringRestController {
	
	public PredictionQueryRestController( PredictionService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Prediction using a UUID
     * @param		UUID predictionId
     * @return		Prediction
     */    
    @GetMapping("/load")
    public Prediction load( @RequestParam(required=true) UUID predictionId ) {
    	Prediction entity = null;

    	try {  
    		entity = service.getPrediction( new PredictionFetchOneSummary( predictionId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Prediction using Id " + predictionId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Prediction business objects
     * @return		Set<Prediction>
     */
    @GetMapping("/")
    public List<Prediction> loadAll() {                
    	List<Prediction> predictionList = null;
        
    	try {
            // load the Prediction
            predictionList = service.getAllPrediction();
            
            if ( predictionList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Predictions" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Predictions ", exc );
        	return null;
        }

        return predictionList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Prediction prediction = null;
    protected PredictionService service = null;
    private static final Logger LOGGER = Logger.getLogger(PredictionQueryRestController.class.getName());
    
}
